calls.name:
raw[..count as usize]
            .iter()
            .filter_map(|event| match event.kind {
                0 => Some(Event::CloseRequested),
                1 => Some(Event::Resized {
                    width: event.width,
                    height: event.height,
                }),
                2 => Some(Event::Key {
                    code: event.code,
                    pressed: event.pressed != 0,
                }),
                3 => Some(Event::PointerMoved {
                    x: event.x,
                    y: event.y,
                }),
                4 => Some(Event::PointerButton {
                    button: event.code,
                    pressed: event.pressed != 0,
                }),
                _ => None,
            })
            .collect
